import asyncio
from functools import cache
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@cache
async def get_cached_dependency():
    return {"message": "Hello from cached dependency!"}

@app.get("/")
async def root(dep: dict = Depends(get_cached_dependency)):
    return dep

client = TestClient(app)

def test_cached_dependency():
    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == {"message": "Hello from cached dependency!"}

@cache
async def get_cached_async_gen():
    yield "value"

@app.get("/gen")
async def gen_root(dep: str = Depends(get_cached_async_gen)):
    return {"dep": dep}

def test_cached_async_gen_dependency():
    response = client.get("/gen")
    assert response.status_code == 200
    assert response.json() == {"dep": "value"}
